class HitCounter {
    queue<int> hits;
public:
    HitCounter() {}
    void hit(int timestamp) {
        hits.push(timestamp);
    }
    int getHits(int timestamp) {
        while (!hits.empty() && hits.front() <= timestamp - 300) {
            hits.pop();
        }
        return hits.size();
    }
};

snippets.java:
class HitCounter {
    private Queue<Integer> hits = new LinkedList<>();
    public HitCounter() {}
    public void hit(int timestamp) {
        hits.add(timestamp);
    }
    public int getHits(int timestamp) {
        while (!hits.isEmpty() && hits.peek() <= timestamp - 300) {
            hits.poll();
        }
        return hits.size();
    }
}

